INSERT INTO destinations (name, title, blurb, image, sort, i18n) VALUES ('Турция', 'Турция и Грузия', 'Черноморское побережье: Трабзон, Ризе, Батуми', 'img/hero-rize-batumi.webp', 1, '{"uz": {"title": "Turkiya va Gruziya", "blurb": "Qora dengiz sohili: Trabzon, Rize, Batumi"}, "en": {"title": "Türkiye and Georgia", "blurb": "The Black Sea coast: Trabzon, Rize, Batumi"}, "tr": {"title": "Türkiye ve Gürcistan", "blurb": "Karadeniz kıyısı: Trabzon, Rize, Batum"}}');
INSERT INTO destinations (name, title, blurb, image, sort, i18n) VALUES ('Умра', 'Умра · Мекка и Медина', 'Паломничество: Мекка, Медина, Джидда', '', 2, '{"uz": {"title": "Umra · Makka va Madina", "blurb": "Ziyorat: Makka, Madina, Jidda"}, "en": {"title": "Umrah · Mecca and Medina", "blurb": "Pilgrimage: Mecca, Medina, Jeddah"}, "tr": {"title": "Umre · Mekke ve Medine", "blurb": "Hac ziyareti: Mekke, Medine, Cidde"}}');
INSERT INTO tours (code, name, destination, agency_commission, operator_commission, is_bookable, published_at, note, description, kicker, nights, from_price, i18n) VALUES ('KARADENIZ', 'Батуми - Ризе - Трабзон', 'Турция', 50, 0, 1, datetime('now'), 'Еженедельные заезды, цены по типу размещения', 'Комбинированный групповой тур по Чёрному морю: Батуми, Ризе и Трабзон за 8 дней. Сопровождение узбекского гида, более 15 экскурсий, отели на первой береговой линии, трансферы на микроавтобусах Sprinter и ужин в грузинской семье.', 'Загадочный Карадениз', 7, NULL, '{"uz": {"name": "Batumi - Rize - Trabzon", "note": "Har haftalik jo‘nashlar, narxlar joylashuv turiga qarab", "description": "Qora dengiz bo‘ylab kombinatsiyalangan guruh turi: 8 kunda Batumi, Rize va Trabzon. O‘zbek gid hamrohligi, 15 dan ortiq ekskursiya, birinchi qator sohil mehmonxonalari, Sprinter mikroavtobuslarida transferlar va gruzin oilasida kechki ovqat."}, "en": {"name": "Batumi – Rize – Trabzon", "note": "Weekly departures, prices by room type", "description": "A combined group tour of the Black Sea: Batumi, Rize and Trabzon in 8 days. An Uzbek guide throughout, more than 15 excursions, seafront hotels, Sprinter minibus transfers and dinner with a Georgian family."}, "tr": {"name": "Batum - Rize - Trabzon", "note": "Haftalık hareketler, fiyatlar oda tipine göre", "description": "Karadeniz boyunca kombine grup turu: 8 günde Batum, Rize ve Trabzon. Özbek rehber eşliğinde, 15’ten fazla gezi, sahil hattında oteller, Sprinter minibüslerle transferler ve bir Gürcü ailesinde akşam yemeği."}}');
INSERT INTO tours (code, name, destination, agency_commission, operator_commission, is_bookable, published_at, note, description, kicker, nights, from_price, i18n) VALUES ('UMRA_TAJ13', 'Умра · TAJ-13', 'Умра', 50, 0, 1, datetime('now'), 'Август—сентябрь еженедельно; осенние заезды (октябрь—декабрь) уточняются у оператора.', 'Умра по программе TAJ-13 (13 дней / 12 ночей). Ташкент → Джидда → Мекка → Медина → Ташкент. Джидда · Hawada Hotel Jeddah · 1 ночь; Мекка · Taj Park · 990 м до Харама · 8 ночей; Медина · Grand Al Shahba · 250 м до мечети Пророка · 3 ночи.', 'Умра · Мекка и Медина', 12, 1200, '{"uz": {"note": "Avgust—sentabr har hafta; kuzgi jo‘nashlar (oktabr—dekabr) operator bilan aniqlanadi.", "name": "Umra · TAJ-13", "description": "TAJ-13 dasturi bo‘yicha umra (13 kun / 12 kecha). Toshkent → Jidda → Makka → Madina → Toshkent. Jidda · Hawada Hotel Jeddah · 1 kecha; Makka · Taj Park · Haramgacha 990 m · 8 kecha; Madina · Grand Al Shahba · Payg‘ambar masjidigacha 250 m · 3 kecha."}, "en": {"note": "Weekly in August–September; autumn departures (October–December) to be confirmed with the operator.", "name": "Umrah · TAJ-13", "description": "Umrah under the TAJ-13 programme (13 days / 12 nights). Tashkent → Jeddah → Mecca → Medina → Tashkent. Jeddah · Hawada Hotel Jeddah · 1 night; Mecca · Taj Park · 990 m to the Haram · 8 nights; Medina · Grand Al Shahba · 250 m to the Prophet’s Mosque · 3 nights."}, "tr": {"note": "Ağustos–Eylül her hafta; sonbahar hareketleri (Ekim–Aralık) operatörle netleştirilir.", "name": "Umre · TAJ-13", "description": "TAJ-13 programıyla umre (13 gün / 12 gece). Taşkent → Cidde → Mekke → Medine → Taşkent. Cidde · Hawada Hotel Jeddah · 1 gece; Mekke · Taj Park · Harem’e 990 m · 8 gece; Medine · Grand Al Shahba · Mescid-i Nebevi’ye 250 m · 3 gece."}}');
INSERT INTO tours (code, name, destination, agency_commission, operator_commission, is_bookable, published_at, note, description, kicker, nights, from_price, i18n) VALUES ('UMRA_TAJ13P', 'Умра · TAJ-13+', 'Умра', 50, 0, 1, datetime('now'), 'Июль—август по указанным датам.', 'Умра по программе TAJ-13+ (13 дней / 12 ночей). Ташкент → Джидда → Мекка → Медина → Ташкент. Джидда · Hawada Hotel Jeddah · 1 ночь; Мекка · Taj Park · 990 м до Харама · 8 ночей; Медина · Mukhtara Plaza · 250 м до мечети Пророка · 3 ночи.', 'Умра · Мекка и Медина', 12, 1250, '{"uz": {"note": "Iyul—avgust — ko‘rsatilgan sanalarda.", "name": "Umra · TAJ-13+", "description": "TAJ-13+ dasturi bo‘yicha umra (13 kun / 12 kecha). Toshkent → Jidda → Makka → Madina → Toshkent. Jidda · Hawada Hotel Jeddah · 1 kecha; Makka · Taj Park · Haramgacha 990 m · 8 kecha; Madina · Mukhtara Plaza · Payg‘ambar masjidigacha 250 m · 3 kecha."}, "en": {"note": "July–August, on the dates listed.", "name": "Umrah · TAJ-13+", "description": "Umrah under the TAJ-13+ programme (13 days / 12 nights). Tashkent → Jeddah → Mecca → Medina → Tashkent. Jeddah · Hawada Hotel Jeddah · 1 night; Mecca · Taj Park · 990 m to the Haram · 8 nights; Medina · Mukhtara Plaza · 250 m to the Prophet’s Mosque · 3 nights."}, "tr": {"note": "Temmuz–Ağustos, belirtilen tarihlerde.", "name": "Umre · TAJ-13+", "description": "TAJ-13+ programıyla umre (13 gün / 12 gece). Taşkent → Cidde → Mekke → Medine → Taşkent. Cidde · Hawada Hotel Jeddah · 1 gece; Mekke · Taj Park · Harem’e 990 m · 8 gece; Medine · Mukhtara Plaza · Mescid-i Nebevi’ye 250 m · 3 gece."}}');
