INSERT INTO tour_content (tour_id, kind, sort, text, i18n) SELECT id, 'included', 2, 'Проживание 7 ночей на базе завтраков в отелях на первой береговой линии: Batumi View Luxury (Батуми) и Rhisos Gold Otel Rize (Ризе)', '{"uz": {"text": "Birinchi qator sohil mehmonxonalarida nonushta bilan 7 kecha: Batumi View Luxury (Batumi) va Rhisos Gold Otel Rize (Rize)"}, "en": {"text": "7 nights with breakfast in seafront hotels: Batumi View Luxury (Batumi) and Rhisos Gold Otel Rize (Rize)"}, "tr": {"text": "Sahil hattındaki otellerde kahvaltı dahil 7 gece: Batumi View Luxury (Batum) ve Rhisos Gold Otel Rize (Rize)"}}' FROM tours WHERE code = 'KARADENIZ';
