INSERT INTO tour_content (tour_id, kind, sort, text, i18n) SELECT id, 'included', 5, 'Один гастрономический ужин в грузинской семье под Батуми (Махунцети) — халяльное меню', '{"uz": {"text": "Batumi yaqinidagi gruzin oilasida bitta gastronomik kechki ovqat (Mahuntseti) — halol menyu"}, "en": {"text": "One food-tasting dinner with a Georgian family near Batumi (Makhuntseti) — halal menu"}, "tr": {"text": "Batum yakınında bir Gürcü ailesinde gastronomi akşam yemeği (Mahuntseti) — helal menü"}}' FROM tours WHERE code = 'KARADENIZ';
