INSERT INTO tour_content (tour_id, kind, sort, text, i18n) SELECT id, 'excluded', 5, 'Дополнительные экскурсии в Ризе: Duatepe, Ceceve Bahcesi', '{"uz": {"text": "Rizedagi qo‘shimcha ekskursiyalar: Duatepe, Ceceve Bahcesi"}, "en": {"text": "Optional excursions in Rize: Duatepe, Ceceve Bahcesi"}, "tr": {"text": "Rize’de ek geziler: Duatepe, Ceceve Bahçesi"}}' FROM tours WHERE code = 'KARADENIZ';
