INSERT INTO tour_content (tour_id, kind, sort, text, url, i18n) SELECT id, 'info', 1, 'Грузия безвизовая для граждан Узбекистана — до 1 года по загранпаспорту', NULL, '{"uz": {"text": "Gruziya O‘zbekiston fuqarolari uchun vizasiz — xorijiy pasport bilan 1 yilgacha"}, "en": {"text": "Georgia is visa-free for Uzbek citizens — up to one year on an international passport"}, "tr": {"text": "Gürcistan, Özbekistan vatandaşları için vizesiz — pasaportla 1 yıla kadar"}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, sort, text, url, i18n) SELECT id, 'info', 2, 'На 5-й день — сухопутный переход границы Турция–Грузия, автобус около 3–4 часов', NULL, '{"uz": {"text": "5-kuni Turkiya–Gruziya chegarasidan quruqlikda o‘tiladi, avtobusda taxminan 3–4 soat"}, "en": {"text": "On day 5 there is a land border crossing Türkiye–Georgia, about 3–4 hours by coach"}, "tr": {"text": "5. gün Türkiye–Gürcistan kara sınırı geçişi, otobüsle yaklaşık 3–4 saat"}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, sort, text, url, i18n) SELECT id, 'info', 3, 'Видео о маршруте: Трабзон и Чёрное море (Traveling Faze)', 'https://www.youtube.com/watch?v=hGk2LxB4d60&t=105s', '{"uz": {"text": "Marshrut haqida video: Trabzon va Qora dengiz (Traveling Faze)"}, "en": {"text": "Video about the route: Trabzon and the Black Sea (Traveling Faze)"}, "tr": {"text": "Güzergâh videosu: Trabzon ve Karadeniz (Traveling Faze)"}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'A', 1, 'День 1 · Батуми', 'Ташкент → Батуми, прилёт 23:20. Встреча, трансфер, отель Batumi View Luxury. Вечерняя прогулка и ужин грузинской кухни — по желанию.', '{"uz": {"title": "1-kun · Batumi", "text": "Toshkent → Batumi, qo‘nish 23:20. Kutib olish, transfer, Batumi View Luxury mehmonxonasi. Kechki sayr va gruzin taomlari — ixtiyoriy."}, "en": {"title": "Day 1 · Batumi", "text": "Tashkent → Batumi, arrival 23:20. Meeting, transfer, Batumi View Luxury hotel. An evening walk and Georgian dinner are optional."}, "tr": {"title": "1. gün · Batum", "text": "Taşkent → Batum, iniş 23:20. Karşılama, transfer, Batumi View Luxury oteli. Akşam yürüyüşü ve Gürcü mutfağı — isteğe bağlı."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'A', 2, 'День 2 · Аджария', 'Мост царицы Тамары, водопад Махунцети, крепость Гонио-Апсарос. Обед: грузинская кухня в центре Батуми или узбекская в «Caravan». По желанию зиплайн. Вечером — ужин в грузинской семье в Махунцети.', '{"uz": {"title": "2-kun · Ajariya", "text": "Malika Tamara ko‘prigi, Mahuntseti sharsharasi, Gonio-Apsaros qal’asi. Tushlik: Batumi markazida gruzin yoki «Caravan»da o‘zbek taomlari. Ixtiyoriy zipline. Kechqurun — Mahuntsetida gruzin oilasida kechki ovqat."}, "en": {"title": "Day 2 · Adjara", "text": "Queen Tamar’s bridge, the Makhuntseti waterfall, the Gonio-Apsaros fortress. Lunch: Georgian food in central Batumi or Uzbek at “Caravan”. Zipline optional. In the evening, dinner with a Georgian family in Makhuntseti."}, "tr": {"title": "2. gün · Acara", "text": "Kraliçe Tamara Köprüsü, Mahuntseti Şelalesi, Gonio-Apsaros Kalesi. Öğle yemeği: Batum merkezinde Gürcü ya da «Caravan»da Özbek mutfağı. Zipline isteğe bağlı. Akşam Mahuntseti’de bir Gürcü ailesinde yemek."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'A', 3, 'Дни 3–4 · Батуми', 'Свободные дни: набережная, дельфинарий (доплата), ботанический сад, шопинг, старый город, Башня Алфавита.', '{"uz": {"title": "3–4-kunlar · Batumi", "text": "Bo‘sh kunlar: sohil bo‘yi, delfinariy (qo‘shimcha to‘lov), botanika bog‘i, xarid, eski shahar, Alifbo minorasi."}, "en": {"title": "Days 3–4 · Batumi", "text": "Free days: the promenade, the dolphinarium (extra charge), the botanical garden, shopping, the old town, the Alphabet Tower."}, "tr": {"title": "3–4. günler · Batum", "text": "Serbest günler: sahil bandı, yunus akvaryumu (ek ücret), botanik bahçe, alışveriş, eski şehir, Alfabe Kulesi."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'A', 4, 'День 5 · Батуми → Ризе', 'Переезд на автобусе около 3–4 часов с прохождением границы. Отель, вечерняя прогулка, ужин турецкой кухни — по желанию.', '{"uz": {"title": "5-kun · Batumi → Rize", "text": "Chegaradan o‘tib, avtobusda taxminan 3–4 soat yo‘l. Mehmonxona, kechki sayr, turk taomlari — ixtiyoriy."}, "en": {"title": "Day 5 · Batumi → Rize", "text": "About 3–4 hours by coach, including the border crossing. Hotel, an evening walk, Turkish dinner — optional."}, "tr": {"title": "5. gün · Batum → Rize", "text": "Sınır geçişiyle birlikte otobüsle yaklaşık 3–4 saat. Otel, akşam yürüyüşü, Türk mutfağı — isteğe bağlı."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'A', 5, 'День 6 · Узунгёль и Трабзон', 'Озеро Узунгёль: чай и сувениры. Далее Трабзон с остановками — пещера Карача, смотровая Torul Cam Teras. Вечером шопинг Forum AVM или прогулка по городу.', '{"uz": {"title": "6-kun · Uzungo‘l va Trabzon", "text": "Uzungo‘l ko‘li: choy va sovg‘alar. So‘ng to‘xtashlar bilan Trabzon — Karaca g‘ori, Torul Cam Teras manzaragohi. Kechqurun Forum AVMda xarid yoki shahar bo‘ylab sayr."}, "en": {"title": "Day 6 · Uzungöl and Trabzon", "text": "Lake Uzungöl: tea and souvenirs. Then on to Trabzon with stops — the Karaca cave and the Torul Cam Teras viewpoint. In the evening, shopping at Forum AVM or a walk in town."}, "tr": {"title": "6. gün · Uzungöl ve Trabzon", "text": "Uzungöl: çay ve hediyelik eşya. Ardından duraklarla Trabzon — Karaca Mağarası, Torul Cam Teras seyir terası. Akşam Forum AVM’de alışveriş ya da şehir turu."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'A', 6, 'День 7 · Айдер', 'Айдер Яйласы через чайные плантации: крепость Zilkale, водопад Palovit, плато 1350 м. По желанию гора Хусер.', '{"uz": {"title": "7-kun · Ayder", "text": "Choy plantatsiyalari orqali Ayder Yaylasi: Zilkale qal’asi, Palovit sharsharasi, 1350 m yassitog‘. Ixtiyoriy Huser tog‘i."}, "en": {"title": "Day 7 · Ayder", "text": "Ayder Yaylası through the tea plantations: Zilkale fortress, the Palovit waterfall, the plateau at 1350 m. Mount Huser optional."}, "tr": {"title": "7. gün · Ayder", "text": "Çay bahçelerinden geçerek Ayder Yaylası: Zilkale, Palovit Şelalesi, 1350 m yayla. İsteğe bağlı Huser Dağı."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'A', 7, 'День 8 · Вылет', 'Свободное утро, трансфер в аэропорт. Трабзон → Ташкент, вылет 18:45.', '{"uz": {"title": "8-kun · Uchish", "text": "Bo‘sh ertalab, aeroportga transfer. Trabzon → Toshkent, uchish 18:45."}, "en": {"title": "Day 8 · Departure", "text": "A free morning, transfer to the airport. Trabzon → Tashkent, departure 18:45."}, "tr": {"title": "8. gün · Dönüş", "text": "Serbest sabah, havalimanına transfer. Trabzon → Taşkent, kalkış 18:45."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'B', 1, 'День 1 · Ризе', 'Ташкент → Трабзон, прилёт 17:45. Встреча, трансфер, отель Rhisos Gold Hotel Rize. Вечерняя прогулка и ужин турецкой кухни — по желанию.', '{"uz": {"title": "1-kun · Rize", "text": "Toshkent → Trabzon, qo‘nish 17:45. Kutib olish, transfer, Rhisos Gold Hotel Rize. Kechki sayr va turk taomlari — ixtiyoriy."}, "en": {"title": "Day 1 · Rize", "text": "Tashkent → Trabzon, arrival 17:45. Meeting, transfer, Rhisos Gold Hotel Rize. An evening walk and Turkish dinner are optional."}, "tr": {"title": "1. gün · Rize", "text": "Taşkent → Trabzon, iniş 17:45. Karşılama, transfer, Rhisos Gold Hotel Rize. Akşam yürüyüşü ve Türk mutfağı — isteğe bağlı."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'B', 2, 'День 2 · Узунгёль и Трабзон', 'Озеро Узунгёль, далее Трабзон: пещера Карача, смотровая Torul Cam Teras. Вечером шопинг Forum AVM или прогулка по городу.', '{"uz": {"title": "2-kun · Uzungo‘l va Trabzon", "text": "Uzungo‘l ko‘li, so‘ng Trabzon: Karaca g‘ori, Torul Cam Teras manzaragohi. Kechqurun Forum AVMda xarid yoki shahar bo‘ylab sayr."}, "en": {"title": "Day 2 · Uzungöl and Trabzon", "text": "Lake Uzungöl, then Trabzon: the Karaca cave and the Torul Cam Teras viewpoint. In the evening, shopping at Forum AVM or a walk in town."}, "tr": {"title": "2. gün · Uzungöl ve Trabzon", "text": "Uzungöl, ardından Trabzon: Karaca Mağarası, Torul Cam Teras. Akşam Forum AVM’de alışveriş ya da şehir turu."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'B', 3, 'День 3 · Айдер', 'Айдер Яйласы: крепость Zilkale, водопад Palovit, плато 1350 м. По желанию гора Хусер.', '{"uz": {"title": "3-kun · Ayder", "text": "Ayder Yaylasi: Zilkale qal’asi, Palovit sharsharasi, 1350 m yassitog‘. Ixtiyoriy Huser tog‘i."}, "en": {"title": "Day 3 · Ayder", "text": "Ayder Yaylası: Zilkale fortress, the Palovit waterfall, the plateau at 1350 m. Mount Huser optional."}, "tr": {"title": "3. gün · Ayder", "text": "Ayder Yaylası: Zilkale, Palovit Şelalesi, 1350 m yayla. İsteğe bağlı Huser Dağı."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'B', 4, 'День 4 · Ризе', 'Свободный день: шопинг, набережная, кафе. Дополнительные экскурсии Duatepe и Ceceve Bahcesi — за доплату.', '{"uz": {"title": "4-kun · Rize", "text": "Bo‘sh kun: xarid, sohil bo‘yi, kafelar. Duatepe va Ceceve Bahcesi ekskursiyalari — qo‘shimcha to‘lov evaziga."}, "en": {"title": "Day 4 · Rize", "text": "A free day: shopping, the promenade, cafés. The Duatepe and Ceceve Bahcesi excursions are available at extra cost."}, "tr": {"title": "4. gün · Rize", "text": "Serbest gün: alışveriş, sahil, kafeler. Duatepe ve Ceceve Bahçesi gezileri — ek ücretle."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'B', 5, 'День 5 · Ризе → Батуми', 'Переезд на автобусе около 3–4 часов с прохождением границы. Отель Batumi View Luxury, вечерняя прогулка — по желанию.', '{"uz": {"title": "5-kun · Rize → Batumi", "text": "Chegaradan o‘tib, avtobusda taxminan 3–4 soat yo‘l. Batumi View Luxury mehmonxonasi, kechki sayr — ixtiyoriy."}, "en": {"title": "Day 5 · Rize → Batumi", "text": "About 3–4 hours by coach, including the border crossing. Batumi View Luxury hotel, an evening walk — optional."}, "tr": {"title": "5. gün · Rize → Batum", "text": "Sınır geçişiyle birlikte otobüsle yaklaşık 3–4 saat. Batumi View Luxury oteli, akşam yürüyüşü — isteğe bağlı."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'B', 6, 'День 6 · Аджария', 'Обед в Батуми или в «Caravan». Мост царицы Тамары, водопад Махунцети, крепость Гонио-Апсарос. По желанию зиплайн. Вечером — ужин в грузинской семье в Махунцети.', '{"uz": {"title": "6-kun · Ajariya", "text": "Batumida yoki «Caravan»da tushlik. Malika Tamara ko‘prigi, Mahuntseti sharsharasi, Gonio-Apsaros qal’asi. Ixtiyoriy zipline. Kechqurun — Mahuntsetida gruzin oilasida kechki ovqat."}, "en": {"title": "Day 6 · Adjara", "text": "Lunch in Batumi or at “Caravan”. Queen Tamar’s bridge, the Makhuntseti waterfall, the Gonio-Apsaros fortress. Zipline optional. In the evening, dinner with a Georgian family in Makhuntseti."}, "tr": {"title": "6. gün · Acara", "text": "Batum’da ya da «Caravan»da öğle yemeği. Kraliçe Tamara Köprüsü, Mahuntseti Şelalesi, Gonio-Apsaros Kalesi. Zipline isteğe bağlı. Akşam Mahuntseti’de bir Gürcü ailesinde yemek."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, variant, sort, title, text, i18n) SELECT id, 'day', 'B', 7, 'Дни 7–8 · Батуми', 'Свободные дни: набережная, дельфинарий (доплата), ботанический сад, шопинг, старый город, Башня Алфавита. День 8 — вылет из Батуми.', '{"uz": {"title": "7–8-kunlar · Batumi", "text": "Bo‘sh kunlar: sohil bo‘yi, delfinariy (qo‘shimcha to‘lov), botanika bog‘i, xarid, eski shahar, Alifbo minorasi. 8-kuni Batumidan uchish."}, "en": {"title": "Days 7–8 · Batumi", "text": "Free days: the promenade, the dolphinarium (extra charge), the botanical garden, shopping, the old town, the Alphabet Tower. Day 8 — departure from Batumi."}, "tr": {"title": "7–8. günler · Batum", "text": "Serbest günler: sahil bandı, yunus akvaryumu (ek ücret), botanik bahçe, alışveriş, eski şehir, Alfabe Kulesi. 8. gün Batum’dan dönüş."}}' FROM tours WHERE code = 'KARADENIZ';
INSERT INTO tour_content (tour_id, kind, sort, text, i18n) SELECT id, 'included', 1, 'Centrum Air · TAS–JED 06:20–11:10 · MED–TAS 17:30–01:50', NULL FROM tours WHERE code = 'UMRA_TAJ13';
INSERT INTO tour_content (tour_id, kind, sort, text, i18n) SELECT id, 'included', 2, 'Джидда · Hawada Hotel Jeddah · 1 ночь', '{"uz": {"text": "Jidda · Hawada Hotel Jeddah · 1 kecha"}, "en": {"text": "Jeddah · Hawada Hotel Jeddah · 1 night"}, "tr": {"text": "Cidde · Hawada Hotel Jeddah · 1 gece"}}' FROM tours WHERE code = 'UMRA_TAJ13';
